/** A verse for a need, rotating so repeat visits don't always get the same one. */
export function verseForNeed(needId: string, exclude?: string): Verse {
  const pool = versiculos.filter((v) => v.needs.includes(needId) && v.ref !== exclude)
  const list = pool.length ? pool : versiculos.filter((v) => v.needs.includes("general"))
  return list[Math.floor(Math.random() * list.length)]
}
